create table if not exists public.ad_events (id uuid primary key default gen_random_uuid(), advertisement_id uuid not null references public.advertisements(id) on delete cascade, organization_id uuid not null references public.organizations(id) on delete cascade, event_type text not null check (event_type in ('impression','click')), created_at timestamptz not null default now());
alter table public.ad_events enable row level security;
create policy "admins read ad events" on public.ad_events for select to authenticated using (public.is_organization_admin(organization_id));
create or replace function public.record_ad_event(target_advertisement_id uuid, target_event_type text) returns uuid language plpgsql security definer set search_path=public as $$ declare event_id uuid; declare org_id uuid; begin select organization_id into org_id from public.advertisements where id=target_advertisement_id and status='published'; if org_id is null then raise exception 'advertisement unavailable'; end if; insert into public.ad_events(advertisement_id,organization_id,event_type) values(target_advertisement_id,org_id,target_event_type) returning id into event_id; if target_event_type='click' then update public.advertisements set click_count=click_count+1 where id=target_advertisement_id; end if; return event_id; end; $$;
grant execute on function public.record_ad_event(uuid,text) to anon, authenticated;
